import{_ as e,I as o,g as l,j as a}from"./chunks/framework.CjoWWfVe.js";const g=JSON.parse('{"title":"ПРО: Мультипространства и Личные финансы","description":"Управление несколькими бизнесами в одной программе, единый бэкап и революционная автоматическая консолидация личных трат.","frontmatter":{"title":"ПРО: Мультипространства и Личные финансы","description":"Управление несколькими бизнесами в одной программе, единый бэкап и революционная автоматическая консолидация личных трат.","order":15},"headers":[],"relativePath":"ru/docs/spaces/moy-kapital/pro-mode.md","filePath":"ru/docs/spaces/moy-kapital/pro-mode.md"}'),r={name:"ru/docs/spaces/moy-kapital/pro-mode.md"};function i(s,t,n,d,c,p){return o(),l("div",null,[...t[0]||(t[0]=[a('<h1 id="👑-про-режим-экосистема-для-масштабирования" tabindex="-1">👑 ПРО-режим: Экосистема для масштабирования <a class="header-anchor" href="#👑-про-режим-экосистема-для-масштабирования" aria-label="Permalink to &quot;👑 ПРО-режим: Экосистема для масштабирования&quot;">​</a></h1><p><strong>ПРО-режим</strong> — это премиум-архитектура ОмниКрафт ЕРП, которая превращает локальную программу из инструмента учёта одной мастерской в полноценную <strong>экосистему управления капиталом</strong>.</p><p>Этот режим открывает две революционные возможности:</p><ol><li><strong>Мультипространства (Multi-Workspaces):</strong> Ведение нескольких независимых бизнесов с изолированными базами данных.</li><li><strong>Глобальная вкладка «Мой капитал»:</strong> Автоматический учёт личных финансов через математическую дельту, без необходимости вбивать каждый чек за кофе.</li></ol><div class="info custom-block"><p class="custom-block-title">Как активировать ПРО?</p><p>ПРО-режим активируется флагом в вашем лицензионном ключе. Как только ключ с типом <code>Про</code> вводится во вкладке «Настройки», программа мгновенно разблокирует выдвижную боковую панель и глобальные инструменты консолидации.</p></div><hr><h2 id="🗂️-мультипространства-multi-workspaces" tabindex="-1">🗂️ Мультипространства (Multi-Workspaces) <a class="header-anchor" href="#🗂️-мультипространства-multi-workspaces" aria-label="Permalink to &quot;🗂️ Мультипространства (Multi-Workspaces)&quot;">​</a></h2><p>Многие ремесленники со временем запускают смежные направления: основная кожевенная мастерская, продажа электронных лекал, преподавание на курсах или ремонт изделий. Смешивать всё это в одной базе — плохая идея: разные валюты, разные наценки, разный склад и абсолютно разная экономика.</p><p>ПРО-режим позволяет создавать <strong>неограниченное количество изолированных рабочих пространств</strong>. Каждое пространство — это полноценная, отдельная база данных SQLite со своими справочниками, рецептами, складом и историей продаж.</p><h3 id="🎛️-как-это-работает-боковая-шторка" tabindex="-1">🎛️ Как это работает (Боковая шторка) <a class="header-anchor" href="#🎛️-как-это-работает-боковая-шторка" aria-label="Permalink to &quot;🎛️ Как это работает (Боковая шторка)&quot;">​</a></h3><p>В верхней правой части окна появляется кнопка <strong>«Пространства и Модули»</strong>. При нажатии на неё выезжает правая боковая шторка, которая становится вашим главным диспетчерским пультом.</p><p>В верхней секции шторки отображается список всех созданных вами пространств:</p><ul><li>🟢 <strong>Зелёная иконка:</strong> Текущее активное пространство, данные которого вы сейчас видите на экране.</li><li>⚪ <strong>Серая иконка:</strong> Другие зарегистрированные базы. Нажмите на них, чтобы мгновенно переключиться.</li></ul><p>При переключении программа на лету подменяет путь к активной базе данных. Интерфейс (вкладки Мастерской, Калькулятора, ДДС и т.д.) мгновенно перезагружается, подтягивая цифры, остатки и аналитику выбранного бизнеса.</p><h3 id="➕-создание-нового-пространства" tabindex="-1">➕ Создание нового пространства <a class="header-anchor" href="#➕-создание-нового-пространства" aria-label="Permalink to &quot;➕ Создание нового пространства&quot;">​</a></h3><p>Внизу списка находится кнопка <strong>«Добавить пространство»</strong>. При нажатии открывается диалог, где вы вводите понятное имя (например, <em>«Выкройки и ПДФ»</em> или <em>«Кожевенный ремонт»</em>).</p><p>Программа автоматически:</p><ol><li>Генерирует уникальный ID и создаёт новый физический файл базы данных в защищённой системной папке.</li><li>Инициализирует в нём все необходимые таблицы (Склад, Верстак, ДДС, Капитал и т.д.).</li><li>Регистрирует пространство в глобальном реестре <code>workspaces.json</code>.</li></ol><div class="tip custom-block"><p class="custom-block-title">Изоляция данных</p><p>Пространства полностью независимы. У каждого бизнеса своя ставка мастера, своя глобальная наценка, свои статьи накладных расходов и свой склад сырья. Вы можете вести один бизнес в рублях, а второй — в долларах или евро, просто измени валюту учёта в настройках конкретного пространства.</p></div><hr><h2 id="💾-единыи-глобальныи-бэкап" tabindex="-1">💾 Единый глобальный бэкап <a class="header-anchor" href="#💾-единыи-глобальныи-бэкап" aria-label="Permalink to &quot;💾 Единый глобальный бэкап&quot;">​</a></h2><p>В ПРО-режиме система резервного копирования эволюционирует. Вместо того чтобы экспортировать каждую базу данных по отдельности, программа упаковывает <strong>абсолютно всё</strong> в один сжатый архив:</p><ul><li>🗃️ Реестр пространств (<code>workspaces.json</code>).</li><li>📦 Базу данных по умолчанию (<code>omnicraft_erp.db</code>).</li><li>📁 Всю папку <code>workspaces/</code> со всеми дополнительными бизнесами.</li><li>💳 Глобальную базу личных финансов (<code>personal_finance.db</code>).</li></ul><p>Это означает, что для полного переноса вашей экосистемы на новый компьютер или для создания страховочной копии вам достаточно сделать <strong>один клик</strong> в меню <code>Файл ➔ Экспорт данных</code>.</p><hr><h2 id="🏦-глобальная-вкладка-«мои-капитал»-личные-финансы" tabindex="-1">🏦 Глобальная вкладка «Мой капитал» (Личные финансы) <a class="header-anchor" href="#🏦-глобальная-вкладка-«мои-капитал»-личные-финансы" aria-label="Permalink to &quot;🏦 Глобальная вкладка «Мой капитал» (Личные финансы)&quot;">​</a></h2><p>Это, пожалуй, самая инновационная функция ОмниКрафт ЕРП. Она решает главную боль любого предпринимателя: <strong>как учитывать личные деньги, не превращаясь в бухгалтера, который вбивает в таблицу каждую покупку хлеба?</strong></p><p>В ПРО-режиме в боковой шторке появляется крупная кнопка <strong>«Мой капитал»</strong>. При её нажатии стандартные бизнес-вкладки скрываются, и открывается глобальная сводная панель, разделённая на четыре подраздела.</p><h3 id="_1-💳-мои-счета-и-инвестиции" tabindex="-1">1. 💳 Мои счета и инвестиции <a class="header-anchor" href="#_1-💳-мои-счета-и-инвестиции" aria-label="Permalink to &quot;1. 💳 Мои счета и инвестиции&quot;">​</a></h3><p>Единый центр вашей ликвидности вне бизнеса. Здесь вы заводите карточки для:</p><ul><li>Банковских карт (дебетовые, кредитные).</li><li>Наличных средств.</li><li>Брокерских счетов (акции, облигации).</li><li>Валютных кошельков и крипто-счетов.</li><li>Депозитов и копилок.</li></ul><p><strong>Как вести учёт:</strong> Вам не нужно записывать каждую транзакцию по карте. Достаточно периодически (например, раз в неделю или в день зарплаты) заходить в этот раздел, нажимать иконку карандаша на карточке счета и просто <strong>вписывать его фактический текущий остаток</strong>. Программа сама зафиксирует дельту.</p><h3 id="_2-🏠-мои-активы" tabindex="-1">2. 🏠 Мои активы <a class="header-anchor" href="#_2-🏠-мои-активы" aria-label="Permalink to &quot;2. 🏠 Мои активы&quot;">​</a></h3><p>Учёт крупного и мелкого личного имущества, не связанного с бизнесом:</p><ul><li>Недвижимость (квартира, земля).</li><li>Транспортные средства.</li><li>Дорогие личные вещи (техника, украшения).</li></ul><p>Вы указываете стоимость покупки и текущую оценочную стоимость. Эти цифры формируют ваш личный Чистые активы.</p><h3 id="_3-📝-значимые-операции" tabindex="-1">3. 📝 Значимые операции <a class="header-anchor" href="#_3-📝-значимые-операции" aria-label="Permalink to &quot;3. 📝 Значимые операции&quot;">​</a></h3><p>Журнал для учёта только <strong>существенных</strong> внешних потоков, которые нельзя игнорировать:</p><ul><li><em>Внешние доходы:</em> Зарплата по найму, разовый фриланс, дивиденды, донаты.</li><li><em>Целевые расходы:</em> Платеж по ипотеке, покупка путевки, крупные медицинские траты.</li></ul><h3 id="_4-📊-информационная-панель-магия-консолидации" tabindex="-1">4. 📊 Информационная панель (Магия консолидации) <a class="header-anchor" href="#_4-📊-информационная-панель-магия-консолидации" aria-label="Permalink to &quot;4. 📊 Информационная панель (Магия консолидации)&quot;">​</a></h3><p>Сердце вкладки «Мой капитал». Здесь программа сводит воедино данные всех ваших бизнес-пространств и личных счетов, рассчитывая четыре глобальных показателя:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Показатель</th><th style="text-align:left;">Что означает</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>💎 Абсолютный капитал (Чистые активы)</strong></td><td style="text-align:left;">Сумма всех активов всех бизнесов + Личные счета + Личные активы. Ваше совокупное богатство на текущую секунду.</td></tr><tr><td style="text-align:left;"><strong>💰 Заработано в бизнесах</strong></td><td style="text-align:left;">Консолидированная чистая прибыль (P&amp;L) со всех рабочих пространств за всё время.</td></tr><tr><td style="text-align:left;"><strong>📈 Внешние доходы / Накоплено</strong></td><td style="text-align:left;">Сумма всех значимых личных доходов, не связанных с бизнесом.</td></tr><tr><td style="text-align:left;"><strong>🔍 Свободные траты на жизнь</strong></td><td style="text-align:left;">Та самая «магическая» цифра (см. ниже).</td></tr></tbody></table><h4 id="🧠-магическая-формула-свободных-трат" tabindex="-1">🧠 Магическая формула свободных трат <a class="header-anchor" href="#🧠-магическая-формула-свободных-трат" aria-label="Permalink to &quot;🧠 Магическая формула свободных трат&quot;">​</a></h4><p>Как программа узнаёт, сколько вы потратили на жизнь (еду, бензин, кофе, одежду), если вы не вбивали эти чеки? Она вычисляет их <strong>от обратного</strong>, через дельту капитала:</p><p>$$\\text{Свободные траты} = \\text{Прибыль бизнесов} + \\text{Внешние доходы} - \\text{Значимые личные расходы} - \\text{Фактический прирост капитала}$$</p><p><strong>Как это работает на практике:</strong></p><ol><li>Программа видит, что ваш бизнес принес <code>100 000 ₽</code> чистой прибыли.</li><li>Вы получили зарплату на работе <code>50 000 ₽</code> (внесли как Внешний доход).</li><li>Вы заплатили за ипотеку <code>30 000 ₽</code> (внесли как Значимый расход).</li><li><em>Теоретически</em> у вас должно стать больше денег на <code>120 000 ₽</code>.</li><li>Но программа смотрит на ваши реальные банковские карты и видит, что суммарный остаток вырос только на <code>40 000 ₽</code>.</li><li><strong>Вывод:</strong> <code>80 000 ₽</code> вы незаметно потратили на повседневную жизнь. Программа честно покажет эту цифру в блоке «Свободные траты на жизнь».</li></ol><div class="tip custom-block"><p class="custom-block-title">Философия «Учёта без рутины»</p><p>Этот подход полностью избавляет вас от микроменеджмента личного бюджета. Вам не нужно сканировать чеки из супермаркета. Программа выступает в роли честного зеркала: она показывает, какой объем денег «растворяется» в быту, позволяя вам оценивать свой реальный уровень жизни и корректировать финансовые цели, опираясь на твердые математические факты.</p></div><hr><h2 id="🧩-сквозные-тематические-модули-дополнении" tabindex="-1">🧩 Сквозные тематические модули (дополнений) <a class="header-anchor" href="#🧩-сквозные-тематические-модули-дополнении" aria-label="Permalink to &quot;🧩 Сквозные тематические модули (дополнений)&quot;">​</a></h2><p>В будущем в нижней секции выдвижной шторки будут появляться <strong>Сквозные модули</strong> — нишевые инструменты, которые можно докупать отдельно.</p><p>Они называются «сквозными», потому что <strong>не привязаны к конкретной базе данных</strong>. Например, если вы купите «Модуль Базы Выкроек», он будет доступен вам из любого рабочего пространства, позволяя вести единый каталог лекал для всех ваших брендов.</p><p>Управление модулями и их статусом также централизовано в боковой шторке и привязано к вашему единому лицензионному ключу, который «эволюционирует» по мере расширения вашей экосистемы.</p>',53)])])}const u=e(r,[["render",i]]);export{g as __pageData,u as default};
